#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    int done = 0;
    do {
        done++;
        cout << "摆好第 " << done << " 份喵" << endl;
    } while (done < n);
    cout << "一共摆了 " << done << " 份{unit}喵" << endl;
    return 0;
}
